package com.shatteredpixel.shatteredpixeldungeon.apd.mechanics;

import com.shatteredpixel.shatteredpixeldungeon.actors.buffs.*;
import com.shatteredpixel.shatteredpixeldungeon.actors.hero.*;
import com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.cleric.AscendedForm;
import com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.*;
import com.shatteredpixel.shatteredpixeldungeon.apd.ArcanaInfoDisplay;

/** Spell resource and selected effect rules; never casts, selects a target or queries attack skill. */
public final class SpellExplanation {
    private SpellExplanation() {}
    private static String n(float value){return ObfuscationExplanation.number(value);}
    /** UI metadata mirrors the game's learned-spell list; never changes availability. */
    public static ClericSpell spellForTalent(Talent talent){
        if(talent==null)return null;
        switch(talent){
            case HOLY_INTUITION:return HolyIntuition.INSTANCE;
            case SHIELD_OF_LIGHT:return ShieldOfLight.INSTANCE;
            case RECALL_INSCRIPTION:return RecallInscription.INSTANCE;
            case SUNRAY:return Sunray.INSTANCE;
            case DIVINE_SENSE:return DivineSense.INSTANCE;
            case BLESS:return BlessSpell.INSTANCE;
            case CLEANSE:return Cleanse.INSTANCE;
            case HOLY_LANCE:return HolyLance.INSTANCE;
            case HALLOWED_GROUND:return HallowedGround.INSTANCE;
            case MNEMONIC_PRAYER:return MnemonicPrayer.INSTANCE;
            case LAY_ON_HANDS:return LayOnHands.INSTANCE;
            case AURA_OF_PROTECTION:return AuraOfProtection.INSTANCE;
            case WALL_OF_LIGHT:return WallOfLight.INSTANCE;
            case DIVINE_INTERVENTION:return DivineIntervention.INSTANCE;
            case JUDGEMENT:return Judgement.INSTANCE;
            case FLASH:return Flash.INSTANCE;
            case BODY_FORM:return BodyForm.INSTANCE;
            case MIND_FORM:return MindForm.INSTANCE;
            case SPIRIT_FORM:return SpiritForm.INSTANCE;
            case BEAMING_RAY:return BeamingRay.INSTANCE;
            case LIFE_LINK:return LifeLinkSpell.INSTANCE;
            case STASIS:return Stasis.INSTANCE;
            default:return null;
        }
    }
    public static String talentDetails(Talent talent,Hero hero){
        if(hero==null||hero.heroClass!=HeroClass.CLERIC||!hero.hasTalent(talent))return "";
        ClericSpell spell=spellForTalent(talent);
        return spell==null?"":"_Current learned spell rules_\nAt your current talent rank:\n\n"+details(spell,hero);
    }

    public static String summary(ClericSpell spell,Hero hero){
        if(hero==null)return "Spell cost depends on the active character.";
        return "Tome charge cost: "+n(spell.chargeUse(hero))+".";
    }
    public static String details(ClericSpell spell,Hero hero) {
        String effect=effects(spell,hero);
        return resources(spell,hero)+(effect.isEmpty()?"":"\n\n"+effect);
    }
    private static String resources(ClericSpell spell,Hero hero){
        if(hero==null)return "";
        float cost=spell.chargeUse(hero);
        String text="_Casting cost_\nTome charge cost: _"+n(cost)+"_.";
        if(hero.buff(Talent.SatiatedSpellsTracker.class)!=null&&hero.hasTalent(Talent.SATIATED_SPELLS))text+="\nYour meal bonus is ready: the next spell grants _"+(1+2*hero.pointsInTalent(Talent.SATIATED_SPELLS))+" shield points_, keeping a stronger existing Barrier. A life-linked powered ally shares the benefit. Formula: 1 + 2 × talent rank.";
        if(hero.subClass==HeroSubClass.PALADIN)text+="\nOther spells extend Holy Weapon and Holy Ward by _10 turns per Tome charge spent_, up to 100 turns remaining. Longer existing effects are kept. Direct recasts can exceed this extension limit.";
        AscendedForm.AscendBuff ascended=hero.buff(AscendedForm.AscendBuff.class);
        if(ascended!=null)text+="\nAscended Form spell count: _"+ascended.spellCasts+"_. This cast adds 1 to the count and _"+(int)(10*cost)+" shield points_, subject to the form's shielding rules. Shielding = 10 × Tome charge cost, rounded down. Judgement resets the spell count after casting.";
        return text;
    }
    public static String effects(ClericSpell spell,Hero hero) {
        if(hero==null)return "";
        AscendedForm.AscendBuff ascended=hero.buff(AscendedForm.AscendBuff.class);
        String text="";
        if(spell instanceof GuidingLight){text+="\n\n_Guiding Light_\nDeals _2–8 base magic damage_ and illuminates survivors. While you are a Cleric, illuminated monsters normally cannot dodge attacks. Your weapon's strength requirement must be met; special guard and dodge rules still apply. The first successful attack consumes Illumination.";if(hero.hasTalent(Talent.SEARING_LIGHT))text+=" Your Searing Light adds _"+(1+2*hero.pointsInTalent(Talent.SEARING_LIGHT))+" damage_ to your hit (1 + 2 × talent rank).";if(hero.subClass==HeroSubClass.PRIEST)text+=" When another creature consumes Illumination with an attack, it also deals _"+(hero.lvl+5)+" base magic damage_ (hero level + 5). You get one free Guiding Light cast every _50 turns_; a free cast still takes its normal turn.";}
        else if(spell instanceof ShieldOfLight){int low=1+hero.pointsInTalent(Talent.SHIELD_OF_LIGHT);text+="\n\n_Shield of Light_\nBlocks an extra _"+low+"–"+(2*low)+" damage per hit_ from the chosen enemy, rolling separately for each hit and favoring middle values. Other enemies are unaffected. Choosing another enemy replaces the first. A life-linked powered ally can share the protection.\nBlock range = 1 + talent rank through 2 × (1 + rank). The hero's 4-turn timer includes the following status update; the linked ally starts with 3 turns before duration adjustments. Casting is instant.";}
        else if(spell instanceof Sunray){int rank=hero.pointsInTalent(Talent.SUNRAY),low=rank==2?6:4,high=rank==2?12:8;int time=2+2*rank;text+="\n\n_Sunray_\nDeals _"+low+"–"+high+" base magic damage_; undead and demons take the maximum before defenses. Its first hit on a surviving target blinds for _"+time+" turns_, adjusted by resistance. Cast again while that Sunray blindness is still active to paralyze for the same duration instead, once per target. Later casts cannot blind that target again.\nBlindness and paralysis duration = 2 + 2 × talent rank.";}
        else if(spell instanceof BlessSpell){int rank=hero.pointsInTalent(Talent.BLESS),amount=5+5*rank;text+="\n\n_Bless_\nOn yourself: _"+(2+4*rank)+" turns of Bless_ and _"+amount+" shield points_. On another creature: _"+amount+" turns of Bless_ and up to _"+amount+" HP_ restored. Unused healing becomes Barrier; a stronger existing Barrier is kept. A life-linked powered ally can share the effect.\nBless raises accuracy and evasion scores by _25%_. The actual chance to hit or dodge still depends on the opponent. Durations and healing follow the target's normal rules.";}
        else if(spell instanceof LayOnHands){int amount=LayOnHands.restorationAmount(hero);text+="\n\n_Lay on Hands_\nOn yourself: adds up to _"+amount+" shield points_, without healing HP. On another character: restores up to _"+amount+" HP_, turning unused healing into added Barrier. Barrier from this spell can stack up to _"+(3*amount)+" shield points_; a stronger existing Barrier is kept.\nRequires a target within _1 tile_. Casts instantly and can share its effect with a life-linked powered ally.\nRestoration = 10 + 5 × talent rank. Added Barrier = max(0, min(unused restoration, "+(3*amount)+" − current Barrier)).";}
        else if(spell instanceof Cleanse){int rank=hero.pointsInTalent(Talent.CLEANSE),duration=Math.max(0,2*(rank-1)),shield=10*rank;text+="\n\n_Cleanse_\nRemoves harmful statuses from you and visible allies, including your life-linked powered ally outside sight. It does not remove ally-conversion effects or Lost Inventory, recover a lost backpack, uncurse equipment, or heal HP. Grants _"+shield+" shield points_, keeping a stronger existing Barrier.";if(duration>0)text+=" Also prevents eligible harmful statuses for _"+(duration+1)+" turns_ on the standard timer. This does not prevent direct damage.";text+="\nShielding = 10 × talent rank. Protection timer = 2 × (rank − 1), plus the following status update, when rank is above 1. Casting takes _1 turn_.";}
        else if(spell instanceof Radiance){text+="\n\n_Radiance_\nIlluminates visible non-allied monsters, including neutral creatures. Already illuminated targets instead take _"+(hero.lvl+5)+" base magic damage_ before defenses (hero level + 5). The first cast does not damage an unilluminated target. Surviving active targets are paralyzed for _3 turns_, adjusted by resistance.\nOn floors with a base sight range below 6 tiles, also grants _"+(com.shatteredpixel.shatteredpixeldungeon.Dungeon.isChallenged(com.shatteredpixel.shatteredpixeldungeon.Challenges.DARKNESS)?20:100)+" turns of Light_. Costs _1 turn_.";}
        else if(spell instanceof Flash){int count=ascended==null?0:ascended.flashCasts;text+="\n\n_Flash_\nRequires Ascended Form. Teleports up to _"+Flash.maximumDistance(hero)+" tiles_ to a mapped or visited, non-solid tile. Requires an unoccupied destination connected by traversable terrain; a straight line of sight is not needed.\nFlash casts in this form: _"+count+"_. Current Tome charge cost: _"+n(spell.chargeUse(hero))+"_ (2 + previous Flash casts). A successful teleport takes _1 turn_ and raises the next cast's cost by 1. Invalid or cancelled attempts spend nothing. Refreshing the same form does not reset the count. Range = 2 + talent rank.";}
        else if(spell instanceof DivineIntervention){int shield=DivineIntervention.shieldOffer(hero),rank=hero.pointsInTalent(Talent.DIVINE_INTERVENTION);text+="\n\n_Divine Intervention_\nGrants _"+shield+" shield points_ to your Ascended Form and allies, including those outside sight. Keeps stronger existing shields. Your form's ordinary cast-shield bonus is applied first; the result is raised to at least "+shield+", rather than adding another "+shield+" on top.\nExtends Ascended Form by _"+(2+rank)+" turns_. Usable _once per form_; refreshing the same form does not reset it. Allies lose this protection when your form ends. Costs _1 turn_ and _5 Tome charges_.\nShielding = 100 + 50 × talent rank; form extension = 2 + rank.";}
        else if(spell instanceof HolyIntuition){text+="\n\n_Holy Intuition's limited identification_\nChecks whether one eligible equipment item or wand is cursed. It sets curse knowledge, not full identification: hidden upgrade levels and other unidentified properties stay hidden. The selector requires an item that is not fully identified and whose curse status is still unknown; ordinary consumables are not eligible. Current cost: "+n(spell.chargeUse(hero))+" Tome charge units = 4 − talent rank. Completing a valid selection spends one game-time unit; cancelling does not apply that item's effect or consume the cast. Viewing this explanation does not check any inventory item's hidden curse state.";}
        else if(spell instanceof RecallInscription){text+="\n\n_Recalling a used inscription_\nThe Cleric's talent records a qualifying used scroll or runestone. An Upgrade scroll does not replace this record. Rank one offers a 10-unit recall window; rank two offers 300 scheduled game-time units, before duration adjustments. A new qualifying use replaces the recorded item and keeps the longer of the remaining window and the newly offered duration. Recalling replays the recorded item's effect and consumes the record; the effect keeps its own targeting and action behavior. Recalled scrolls disable on-scroll talent triggers rather than repeatedly granting those benefits.\nTome costs follow the recorded class: ordinary scrolls 3, Transmutation 6; exotic scrolls 4, Metamorphosis or Enchantment 8; runestones 2, Augmentation or Enchantment stones 4. Current cost from the existing record: "+n(spell.chargeUse(hero))+" charge units. A zero cost with no record does not make the spell available. This explanation does not instantiate or activate the recorded item.";}
        else if(spell instanceof BodyForm){int duration=Math.round(13.33f+6.67f*hero.pointsInTalent(Talent.BODY_FORM));text+="\n\n_Configuring Trinity's body effect_\nChoose a discovered enchantment or glyph for Trinity's body slot. Confirming the selection pays "+n(spell.chargeUse(hero))+" Tome charge units; it does not permanently inscribe a carried weapon or armor. Activating that stored form later uses the armor ability's separate charge cost. The body effect's offered duration is round(13.33 + 6.67 × Body Form rank) = "+duration+" scheduled game-time units. The chosen effect keeps its own trigger, strength, immunity and stacking rules; this duration is not extra damage points or a permanent upgrade.";}
        else if(spell instanceof MindForm){int level=2+hero.pointsInTalent(Talent.MIND_FORM);text+="\n\n_Configuring Trinity's mind effect_\nChoose a discovered wand or thrown-weapon type, including eligible tipped darts. Confirming the selection pays "+n(spell.chargeUse(hero))+" Tome charge units. Activating the stored effect later uses the armor ability's separate charge cost and that effect's targeting, collision and action rules. Its simulated item level is 2 + Mind Form rank = +"+level+"; this does not upgrade a weapon or wand in your inventory. Wand effects and thrown attacks still use their own damage/charge/target calculations. Viewing the description does not prepare, identify, refill or throw the stored effect.";}
        else if(spell instanceof SpiritForm){int rank=hero.pointsInTalent(Talent.SPIRIT_FORM);text+="\n\n_Configuring Trinity's spirit effect_\nChoose a discovered ring or artifact, excluding the Holy Tome from the artifact list. Confirming the selection pays "+n(spell.chargeUse(hero))+" Tome charge units. Later activation uses armor ability charge; the selected type determines whether it grants a timed passive effect or a particular active artifact effect. Ring item level follows Spirit Form rank: +"+rank+". Artifact visible upgrade level follows 2 + 2 × rank: +"+(2+2*rank)+" on the artifact's normal ten-point upgrade scale. Each item's own formulas interpret those levels; they are not universal damage or percentage bonuses. A passive spirit effect is offered "+n(SpiritForm.SpiritFormBuff.DURATION)+" scheduled game-time units before reapplication rules. The description names stored effects without modifying their levels or granting a physical item.";}
        else if(spell instanceof LifeLinkSpell){int rank=hero.pointsInTalent(Talent.LIFE_LINK);text+="\n\n_Empowered Life Link_\nOffered duration: "+LifeLinkSpell.linkDuration(hero)+" scheduled game-time units = round(6.67 + 3.33 × talent rank), before duration adjustments. Links hero and powered ally for ordinary Life Link damage sharing: each recipient gets ceil(incoming damage / (valid links + 1)), with separate defenses and rounding. The linked ally's Power of Many incoming-damage factor becomes 0.70 − 0.05 × rank = "+n(.70f-.05f*rank)+" instead of 0.75 at that step. This is not a guarantee of that percentage less final HP loss after every defense.\nThe link also enables the paired behavior explicitly supported by Shield of Light, Divine Sense, Bless, Cleanse, Lay on Hands, Hallowed Ground, Mnemonic Prayer and the ready meal-shield benefit. Stored allies can receive the link while in Stasis, with timing repaired on return. Casting takes one game-time unit and pays two Tome charge units. Inspecting this panel does not resolve the linked character's hidden HP.";}
        else if(spell instanceof BeamingRay){int rank=hero.pointsInTalent(Talent.BEAMING_RAY);text+="\n\n_Beaming the powered ally_\nMovement range from the ally's position: "+BeamingRay.movementRange(hero,false)+" tiles = 4 × talent rank; an immovable ally instead uses "+BeamingRay.movementRange(hero,true)+" tiles. The destination must be visible and suitable. A blocked or occupied target can redirect the landing to an eligible neighboring tile; this is not permission to land on another character. A stored ally can be returned from Stasis.\nA selected enemy can become the directed target; otherwise the existing fallback chooses a hostile within four tiles of the landing point, preferring a more distant candidate when comparing candidates. No hidden target location is displayed here. For "+n(BeamingRay.BeamingRayBoost.DURATION)+" scheduled units, Power of Many's attack-damage factor against that directed target becomes 1.30 + 0.05 × rank = "+n(1.30f+.05f*rank)+", replacing its ordinary 1.25 factor at that step. Other targets and damage paths keep their own rules. The boost does not independently guarantee a hit. Casting takes one game-time unit and pays the current Tome cost.";}
        else if(spell instanceof Stasis){int duration=30+30*hero.pointsInTalent(Talent.STASIS);text+="\n\n_Storing and releasing the ally_\nOffered storage duration: "+duration+" scheduled game-time units = 30 + 30 × talent rank. Storing the powered ally removes it from active floor actors; positive and revival-persistent buffs are retained rather than ticking normally while stored. Other buffs are not all preserved. The stored creature and retained state are saved with the hero's Stasis effect.\nStoring costs two Tome charge units and one game-time unit. Recasting while an ally is already stored costs zero Tome charges and adds no action-time spend, but still runs the ordinary spell-cast side effects. Release normally chooses an unoccupied neighboring passable tile (or suitable hazard tile for a flying ally). If none exists, the current fallback still picks an adjacent tile; it is not a promise of a clear landing space. Immovable allies are released before a floor transition rather than carried to the next floor. Viewing the description does not release or advance the stored ally.";}
        else if(spell instanceof HallowedGround){int rank=hero.pointsInTalent(Talent.HALLOWED_GROUND);text+="\n\n_Hallowed terrain, healing and shielding_\nTargets a visible non-solid tile, then covers reachable non-solid tiles within "+rank+" steps; the open-area bounding width is "+(1+2*rank)+" tiles. Walls and floor boundaries reduce the affected area. Each affected tile is seeded with 20 terrain units that decay one per update; fire removes affected terrain early.\nInitial restoration amount: "+HallowedGround.INITIAL_POWER+" points. You and full-health allies instead change Barrier by min("+HallowedGround.INITIAL_POWER+", "+HallowedGround.INITIAL_SHIELD_LIMIT+" − current total shielding). Under this existing rule, the change is negative above that total and can reduce existing Barrier. Injured other allies heal up to "+HallowedGround.INITIAL_POWER+" missing HP; their unused amount is added as Barrier without that initial limit.\nEach later terrain update adds 1 Barrier point to you or a full-health ally, without that initial cap, or restores 1 HP to an injured other ally. Non-flying hostile/neutral creatures are initially illuminated and offered two units of Roots; later updates offer one unit of Cripple once Roots is absent. A qualifying Life Link shares the corresponding friendly effect when only one linked character is in the terrain.\nEligible short grass has a 1 / (10 + 10 × rank) = "+n(100f/HallowedGround.grassGrowthDenominator(hero))+"% growth check per terrain update, not a promise of that percentage of the room becoming tall grass. Disabled passive recovery or the existing growth counter can produce furrowed grass instead. Casting spends one game-time unit and its Tome charge cost.";}
        else if(spell instanceof WallOfLight){int rank=hero.pointsInTalent(Talent.WALL_OF_LIGHT);text+="\n\n_Light panels and removal_\nA cardinal cast attempts up to "+(1+2*rank)+" panels = 1 + 2 × rank directly in front of the hero. Diagonal casts step across both axes and can attempt up to "+(1+4*rank)+" panels in a staircase shape. Solid terrain and floor edges reduce actual placement. Each panel starts with 20 units and loses one per terrain update. Active panels block normal movement and projectiles through their solid-tile rule, while leaving normal sight blocking unchanged. This is not invisibility or full invulnerability.\nA hostile caught at placement is offered a one-tile push under normal collision rules, plus paralysis tied to that character's current action delay. Casting a new wall costs three Tome charges and one game-time unit. While any Light Wall is active on the floor, recasting clears it instead, with zero Tome cost and no action-time spend or ordinary spell-cast side effects. Viewing this explanation does not create or clear a wall.";}
        else if(spell instanceof MnemonicPrayer){int amount=2+hero.pointsInTalent(Talent.MNEMONIC_PRAYER);text+="\n\n_One enhancement per status instance_\nCurrent extension amount: "+amount+" = 2 + talent rank. On an ally, supported positive effects with visible icons can be improved; on another character, supported negative effects can be improved and the target is illuminated. An existing status instance is marked after its first eligible enhancement, so repeated casts do not repeatedly enhance that same instance. Ascended Form, Body/Spirit forms, Power of Many, Beaming Ray boost and Life Link effects are excluded from friendly enhancement.\nMost timed effects gain "+amount+" game-time units after their duration adjustments. This amount is not always time: Healing gains that many requested HP in its reserve, Sungrass gains that many pool points, Greater Haste gains that many movement/update budget units, and Bleeding gains that many intensity points rather than extra turns. Shield effects delay their next decay instead of gaining shield points. Other supported effects extend or delay their own counters; unsupported effects are not promised a benefit.\nThe selected character must be visible. A qualifying Life Link can duplicate the supported paired effect. Casting adds no normal game-time spend but pays Tome charges and runs ordinary spell-cast side effects. Inspection does not apply or mark any status.";}
        else if(spell instanceof DivineSense){int rank=hero.pointsInTalent(Talent.DIVINE_SENSE);text+="\n\n_Divine Sense_\nThe Cleric's creature-sensing range is 4 + 4 × rank = "+(4+4*rank)+" tiles. The alternate non-Cleric talent contribution uses 1 + 2 × rank = "+(1+2*rank)+" tiles. It lasts "+n(DivineSense.DivineSenseTracker.DURATION)+" scheduled turns before reapplication rules and can be shared with an appropriately life-linked ally. This senses eligible creatures rather than mapping every room or guaranteeing a projectile path through walls.";}
        else if(spell instanceof HolyLance){int rank=hero.pointsInTalent(Talent.HOLY_LANCE),low=15+15*rank,high=Math.round(27.5f+27.5f*rank);text+="\n\n_Holy Lance_\nRaw roll bounds: "+low+"–"+high+" damage points. Minimum = 15 + 15 × rank; maximum = round(27.5 + 27.5 × rank). Undead/demonic targets use that maximum before later protection. A completed cast uses one turn and starts a 30-unit scheduled cooldown; throwing at an empty valid location can still spend the action and charge cost. This is not a damage multiplier on the current weapon.";}
        else if(spell instanceof Smite){int low=5+hero.lvl/2,high=10+hero.lvl;float current=EnchantmentExplanation.knownPower(hero);text+="\n\n_Smite_\nAdds a separate raw magic damage roll of "+low+"–"+high+" points: minimum = 5 + floor(hero level / 2), maximum = 10 + hero level. Undead/demonic targets use the maximum. It also adds 3 units to weapon enchantment power for the strike, instead of adding three damage points or multiplying every enchantment's effect by four. ";if(Float.isFinite(current))text+="With known current modifiers, the strike's offered enchantment power is "+n(current+(hero.buff(Smite.SmiteTracker.class)==null?3:0))+". ";else text+="Identify contributing ring bonuses before the combined enchantment-power preview is shown. ";text+="When the weapon's strength requirement is met, the attack uses the game's very large accuracy factor; otherwise the normal factor applies. Special guaranteed evasion and other attack rules can still prevent a hit. The action uses normal attack time; the damage bounds above do not promise final HP lost.";}
        else if(spell instanceof Judgement){int base=5+5*hero.pointsInTalent(Talent.JUDGEMENT),count=ascended==null?0:ascended.spellCasts,total=base+Math.round(base*count/3f);text+="\n\n_Judgement_\nBase minimum = 5 + 5 × rank = "+base+" damage points. Add round(base minimum × spells recorded / 3) = "+Math.round(base*count/3f)+" to that minimum; the maximum is twice the resulting minimum. Current raw range: "+total+"–"+(2*total)+" damage points per eligible visible opposing target. This uses an additive one-third-of-base contribution per recorded spell, not compounding ×1.33 on the previous result. It does not use one shared total split among all targets. The count resets after the spell; later defenses still determine actual HP loss.";}
        else if(spell instanceof AuraOfProtection){int rank=hero.pointsInTalent(Talent.AURA_OF_PROTECTION);float remain=.9f-.1f*rank,add=.25f+.25f*rank;float ring=ArcanaInfoDisplay.knownArcanaPower(hero);text+="\n\n_Aura protection and glyph power_\nQualifying damage is multiplied by 0.9 − 0.1 × rank = "+n(remain)+" at this aura's stage before later protection; this leaves "+n(100*remain)+"% at that step, not guaranteed final HP loss. It applies to the hero and eligible same-alignment allies within two tiles, with the life-link exception. The aura lasts "+n(AuraOfProtection.AuraBuff.DURATION)+" scheduled turns before reapplication rules. Glyph power gains 0.25 + 0.25 × rank = "+n(add)+" added power units after the Arcana contribution; the two contributions are added rather than multiplying Arcana by this bonus. ";if(Float.isFinite(ring))text+="With the current known Arcana contribution, offered glyph power is "+n(ring+add)+". ";else text+="Identify contributing rings before total glyph power is shown. ";text+="An ally already using the glyph does not receive duplicate glyph activations.";}
        else if(spell instanceof HolyWeapon){int base=hero.subClass==HeroSubClass.PALADIN?6:2;float power=EnchantmentExplanation.knownPower(hero);text+="\n\n_Holy Weapon_\nOffers "+base+" base magic damage points on a qualifying surviving target, multiplied by weapon enchantment power and rounded. ";if(Float.isFinite(power))text+="At current known power this offers "+Math.round(base*power)+" raw magic damage points before target protection. ";else text+="Identify contributing ring bonuses for the full preview. ";text+="This is a separate bonus, not a percentage increase to every damage source. The normal worn-weapon path needs magic active and overrides a beneficial enchantment except for the Paladin; curses follow their own rules. The unarmed path is separate and does not use that worn-weapon magic-immunity guard. The spell itself takes no game time, offers 50 scheduled units and still pays its Tome cost. Direct reapplication adds duration; Paladin extensions have the separate limit described above.";}
        else if(spell instanceof HolyWard){int base=hero.subClass==HeroSubClass.PALADIN?3:1;float ring=ArcanaInfoDisplay.knownArcanaPower(hero);text+="\n\n_Holy Ward_\nOffers "+base+" base damage-blocking points at the armor effect's step, scaled by glyph power and rounded. It is not a percentage of the incoming hit or a Barrier reserve. ";if(hero.belongings.armor()!=null){if(Float.isFinite(ring))text+="With current known glyph power this offers "+Math.round(base*(ring+ObfuscationExplanation.aura(hero)))+" blocking points when active. ";else text+="Identify contributing ring bonuses before the full block preview is shown. ";text+="The worn-armor path is disabled by magic immunity and normally overrides a beneficial glyph except for the Paladin. ";}else text+="Without worn armor, the existing separate calculation uses the attacker's glyph power; no single final block value can be inferred without that attack. ";text+="It takes no game time, offers 50 scheduled units and pays its Tome cost. Direct reapplication adds duration; Paladin extensions use the separate limit described above.";}
        return text.trim();
    }
}
